<article><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="<?= e(url()) ?>">Home</a><span>/</span><a href="<?= e(url('blog')) ?>">Blog</a></nav><header class="article-header"><p class="eyebrow"><?= e($post['category_name']??'Article') ?></p><h1><?= e($post['title']) ?></h1><p class="lead"><?= e($post['excerpt']) ?></p><p class="meta"><time datetime="<?= e($post['published_at']) ?>"><?= e(date('F j, Y',strtotime($post['published_at']))) ?></time> · <?= (int)$post['reading_time'] ?> min read<?php if($post['updated_at']!==$post['created_at']):?> · Updated <?= e(date('M j, Y',strtotime($post['updated_at']))) ?><?php endif?></p></header><div class="markdown"><?= $post['rendered'] ?></div><footer class="article-footer"><div class="badges"><?php foreach($post['tags'] as $tag):?><a class="badge" href="<?= e(url('tag/'.$tag['slug'])) ?>"><?= e($tag['name']) ?></a><?php endforeach?></div><p>Written by <strong><?= e($post['author_name']) ?></strong></p><nav class="adjacent"><?php if($adjacent['previous']):?><a href="<?= e(url('blog/'.$adjacent['previous']['slug'])) ?>">← <?= e($adjacent['previous']['title']) ?></a><?php endif?><?php if($adjacent['next']):?><a href="<?= e(url('blog/'.$adjacent['next']['slug'])) ?>"><?= e($adjacent['next']['title']) ?> →</a><?php endif?></nav></footer></article><script type="application/ld+json"><?= json_encode(['@context'=>'https://schema.org','@type'=>'BlogPosting','headline'=>$post['title'],'description'=>$post['excerpt'],'datePublished'=>$post['published_at'],'dateModified'=>$post['updated_at'],'author'=>['@type'=>'Person','name'=>$post['author_name']],'url'=>$canonical],JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE) ?></script>
